    14	        Vec3 { x, y, z }
    15	    }
    16	
    17	    pub fn dot(self, other: Vec3) -> f64 {
    18	        self.x * other.x + self.y * other.y + self.z * other.z
    19	    }
    20	
    21	    pub fn cross(self, other: Vec3) -> Vec3 {
    22	        Vec3::new(
    23	            self.y * other.z - self.z * other.y,
    24	            self.z * other.x - self.x * other.z,
    25	            self.x * other.y - self.y * other.x,
    26	        )
    27	    }
    28	
    29	    pub fn length(self) -> f64 {
    30	        self.dot(self).sqrt()
    31	    }
