     7	/// Where a ray hit a surface: the distance along the ray, the point, the normal that always faces
     8	/// against the ray, the face side and the texture coordinates.
     9	#[derive(Clone, Copy, Debug)]
    10	pub struct HitRecord {
    11	    pub t: f64,
    12	    // The origin of the bounce rays.
    13	    #[allow(dead_code)]
    14	    pub point: Vec3,
    15	    pub normal: Vec3,
    16	    #[allow(dead_code)]
    17	    pub front_face: bool,
    18	    #[allow(dead_code)]
    19	    pub u: f64,
    20	    #[allow(dead_code)]
    21	    pub v: f64,
    22	}
    23	
    24	impl HitRecord {
    25	    /// Build a hit record whose normal faces against the ray, with the face side recorded.
    26	    pub fn new(ray: &Ray, t: f64, point: Vec3, outward_normal: Vec3, u: f64, v: f64) -> Self {
    27	        let front_face = ray.direction.dot(outward_normal) < 0.0;
    28	        let normal = if front_face {
    29	            outward_normal
    30	        } else {
    31	            -outward_normal
    32	        };
    33	        HitRecord {
    34	            t,
    35	            point,
    36	            normal,
    37	            front_face,
    38	            u,
    39	            v,
    40	        }
    41	    }
    42	}
    43	
    44	pub trait Hittable {
    45	    /// The nearest hit with `t` in `t_min..t_max`, if any.
    46	    fn hit(&self, ray: &Ray, t_min: f64, t_max: f64) -> Option<HitRecord>;
    47	
    48	    /// The axis-aligned box around the whole object, or `None` when the object has no finite
    49	    /// extent.
    50	    fn bounding_box(&self) -> Option<Aabb> {
    51	        None
    52	    }
    53	}
    54	
    55	/// A scene: every object, hit in order of distance.
    56	#[derive(Default)]
    57	pub struct HittableList {
    58	    pub objects: Vec<Box<dyn Hittable>>,
    59	}
    60	
    61	impl HittableList {
    62	    pub fn add(&mut self, object: Box<dyn Hittable>) {
    63	        self.objects.push(object);
    64	    }
    65	}
    66	
    67	impl Hittable for HittableList {
    68	    fn hit(&self, ray: &Ray, t_min: f64, t_max: f64) -> Option<HitRecord> {
    69	        let mut nearest: Option<HitRecord> = None;
    70	        for object in &self.objects {
    71	            let limit = nearest.map_or(t_max, |hit| hit.t);
    72	            if let Some(bounds) = object.bounding_box() {
    73	                if !bounds.hit(ray, t_min, limit) {
    74	                    continue;
    75	                }
    76	            }
    77	            if let Some(hit) = object.hit(ray, t_min, limit) {
    78	                nearest = Some(hit);
    79	            }
    80	        }
    81	        nearest
    82	    }
    83	}
