 27	/// The colour seen along a ray: the surface normal where it hits, the sky gradient otherwise.
 28	fn ray_colour(ray: &Ray, world: &dyn Hittable) -> Colour {
 29	    if let Some(hit) = world.hit(ray, 0.001, f64::INFINITY) {
 30	        return (hit.normal + Vec3::new(1.0, 1.0, 1.0)) * 0.5;
 31	    }
 32	    let t = 0.5 * (ray.direction.unit().y + 1.0);
 33	    Vec3::new(1.0, 1.0, 1.0) * (1.0 - t) + Vec3::new(0.5, 0.7, 1.0) * t
 34	}
