 36	fn scene() -> HittableList {
 37	    let mut world = HittableList::default();
 38	    world.add(Box::new(Sphere::new(Vec3::new(0.0, 0.0, -1.0), 0.5)));
 39	    world.add(Box::new(Sphere::new(Vec3::new(0.0, -100.5, -1.0), 100.0)));
