 48	/// Every pixel's colour, row by row from the top.
 49	fn render(width: usize, height: usize) -> Vec<Colour> {
 50	    let world = scene();
 51	    let camera = Camera::new(width as f64 / height as f64);
 52	    let mut pixels = Vec::with_capacity(width * height);
 53	    for row in (0..height).rev() {
 54	        for column in 0..width {
 55	            let u = column as f64 / (width - 1) as f64;
 56	            let v = row as f64 / (height - 1) as f64;
