     1	//! Materials: how a ray scatters when it hits a surface.
     2	
     3	use crate::hittable::HitRecord;
     4	use crate::ray::Ray;
     5	use crate::rng::Rng;
     6	use crate::vec3::{Colour, Vec3};
     7	
     8	/// A surface material: how an incoming ray scatters, or nothing when it is absorbed.
     9	pub trait Material {
    10	    /// The attenuation and the scattered ray, or nothing when the ray is absorbed.
    11	    fn scatter(&self, ray_in: &Ray, hit: &HitRecord, rng: &mut Rng) -> Option<(Colour, Ray)>;
    12	}
    13	
    14	/// A diffuse material that scatters in a random direction around the normal.
    15	pub struct Lambertian {
    16	    pub albedo: Colour,
    17	}
    18	
    19	impl Lambertian {
    20	    /// A diffuse material with the given albedo.
    21	    pub fn new(albedo: Colour) -> Self {
    22	        Lambertian { albedo }
    23	    }
    24	}
    25	
    26	impl Material for Lambertian {
    27	    fn scatter(&self, _ray_in: &Ray, hit: &HitRecord, rng: &mut Rng) -> Option<(Colour, Ray)> {
    28	        let direction = hit.normal + random_unit_vector(rng);
    29	        Some((self.albedo, Ray::new(hit.point, direction)))
    30	    }
    31	}
    32	
    33	/// A metal material that reflects about the normal, blurred by a fuzz factor in 0..=1.
    34	pub struct Metal {
    35	    pub albedo: Colour,
    36	    pub fuzz: f64,
    37	}
    38	
    39	impl Metal {
    40	    /// A metal with the given albedo and a fuzz factor in 0..=1.
    41	    pub fn new(albedo: Colour, fuzz: f64) -> Self {
    42	        Metal { albedo, fuzz }
    43	    }
    44	}
    45	
    46	impl Material for Metal {
    47	    fn scatter(&self, ray_in: &Ray, hit: &HitRecord, rng: &mut Rng) -> Option<(Colour, Ray)> {
    48	        let reflected = reflect(ray_in.direction.unit(), hit.normal);
    49	        let scattered = reflected + random_unit_vector(rng) * self.fuzz;
