 24	const DEFAULT_HEIGHT: usize = 200;
 25	const DEFAULT_SAMPLES: usize = 16;
 26	const DEFAULT_OUTPUT: &str = "render.png";
 27	
 28	const USAGE: &str = "usage: toy-raytracer [--width <pixels>] [--height <pixels>] [--samples <count>] [--output <path>] [--format png|ppm]";
