 44	/// The colour seen along a ray: the surface normal where it hits, the sky gradient otherwise.
 45	fn ray_colour(ray: &Ray, world: &dyn Hittable) -> Colour {
 46	    if let Some(hit) = world.hit(ray, 0.001, f64::INFINITY) {
 47	        return (hit.normal + Vec3::new(1.0, 1.0, 1.0)) * 0.5;
 48	    }
 49	    let t = 0.5 * (ray.direction.unit().y + 1.0);
 50	    Vec3::new(1.0, 1.0, 1.0) * (1.0 - t) + Vec3::new(0.5, 0.7, 1.0) * t
 51	}
 52	
 53	fn scene() -> HittableList {
 54	    let mut world = HittableList::default();
 55	    world.add(Box::new(Sphere::new(Vec3::new(0.0, 0.0, -1.0), 0.5)));
 56	    world.add(Box::new(Sphere::new(Vec3::new(0.0, -100.5, -1.0), 100.0)));
 57	    world
 58	}
 59	
 60	/// Every pixel's colour, row by row from the top, each pixel averaging `samples` rays, with the
 61	/// share of finished rows reported on standard error.
 62	fn render(width: usize, height: usize, samples: usize) -> Vec<Colour> {
 63	    let world = scene();
 64	    let camera = Camera::new(width as f64 / height as f64);
 65	    let mut pixels = Vec::with_capacity(width * height);
 66	    for row in (0..height).rev() {
 67	        for column in 0..width {
 68	            let u = column as f64 / (width - 1) as f64;
 69	            let v = row as f64 / (height - 1) as f64;
 70	            let ray = camera.ray(u, v);
 71	            let mut colour = Colour::new(0.0, 0.0, 0.0);
 72	            for _ in 0..samples {
 73	                colour = colour + ray_colour(&ray, &world);
 74	            }
 75	            pixels.push(colour / samples as f64);
 76	        }
 77	        let done = height - row;
 78	        eprint!("\r{}%", done * 100 / height);
 79	    }
 80	    eprintln!();
 81	    pixels
 82	}
 83	
 84	pub(crate) fn to_byte(channel: f64) -> u8 {
 85	    (255.999 * channel.clamp(0.0, 1.0)) as u8
 86	}
 87	
 88	fn write_ppm(
 89	    out: &mut impl Write,
 90	    width: usize,
 91	    height: usize,
 92	    pixels: &[Colour],
 93	) -> io::Result<()> {
 94	    writeln!(out, "P3\n{width} {height}\n255")?;
 95	    for pixel in pixels {
 96	        writeln!(
 97	            out,
 98	            "{} {} {}",
 99	            to_byte(pixel.x),
100	            to_byte(pixel.y),
101	            to_byte(pixel.z)
102	        )?;
103	    }
104	    Ok(())
105	}
106	
107	/// Resolve the arguments into one set of settings before any rendering starts.
108	fn parse_args(args: &[String]) -> Result<Settings, String> {
109	    let mut width = DEFAULT_WIDTH;
110	    let mut height = DEFAULT_HEIGHT;
111	    let mut samples = DEFAULT_SAMPLES;
112	    let mut output = PathBuf::from(DEFAULT_OUTPUT);
113	    let mut explicit_format = None;
114	
115	    let mut index = 0;
116	    while index < args.len() {
117	        let option = args[index].as_str();
118	        let value = || {
119	            args.get(index + 1)
120	                .map(String::as_str)
121	                .ok_or_else(|| format!("{option} needs a value"))
122	        };
123	        match option {
124	            "--width" => width = parse_dimension(option, value()?)?,
125	            "--height" => height = parse_dimension(option, value()?)?,
126	            "--samples" => {
127	                let value = value()?;
128	                let count = value
129	                    .parse::<usize>()
130	                    .map_err(|_| format!("--samples: {value:?} is not a whole number"))?;
131	                if count < 1 {
132	                    return Err(format!("--samples: {value:?} is less than 1"));
133	                }
134	                samples = count;
135	            }
136	            "--output" => output = PathBuf::from(value()?),
137	            "--format" => {
138	                explicit_format = Some(match value()? {
139	                    "png" => Format::Png,
140	                    "ppm" => Format::Ppm,
141	                    other => return Err(format!("--format: unrecognised format {other:?}")),
142	                });
143	            }
144	            other => return Err(format!("unknown option {other:?}")),
145	        }
146	        index += 2;
147	    }
148	
149	    let format = resolve_format(explicit_format, &output)?;
150	    Ok(Settings {
151	        width,
152	        height,
153	        samples,
154	        output,
155	        format,
156	    })
157	}
158	
159	/// A pixel dimension, which must parse as a whole number of at least 2.
160	fn parse_dimension(option: &str, value: &str) -> Result<usize, String> {
161	    let dimension = value
162	        .parse::<usize>()
163	        .map_err(|_| format!("{option}: {value:?} is not a whole number"))?;
164	    if dimension < 2 {
165	        return Err(format!("{option}: {value:?} is less than 2"));
166	    }
167	    Ok(dimension)
168	}
169	
170	/// An explicit format, or the one named by the output file's extension.
171	fn resolve_format(explicit: Option<Format>, output: &Path) -> Result<Format, String> {
172	    if let Some(format) = explicit {
173	        return Ok(format);
174	    }
175	    match output.extension().and_then(|extension| extension.to_str()) {
176	        Some("png") => Ok(Format::Png),
177	        Some("ppm") => Ok(Format::Ppm),
178	        _ => Err(format!(
179	            "{}: output name has no png or ppm extension and no --format is given",
180	            output.display()
181	        )),
182	    }
183	}
184	
185	fn run(settings: &Settings) -> io::Result<()> {
186	    let pixels = render(settings.width, settings.height, settings.samples);
187	    let mut bytes = Vec::new();
188	    match settings.format {
189	        Format::Png => png::write_png(&mut bytes, settings.width, settings.height, &pixels)?,
190	        Format::Ppm => write_ppm(&mut bytes, settings.width, settings.height, &pixels)?,
191	    }
192	    fs::write(&settings.output, bytes)
193	}
194	
195	fn main() {
196	    let args: Vec<String> = std::env::args().skip(1).collect();
197	    let settings = match parse_args(&args) {
198	        Ok(settings) => settings,
199	        Err(message) => {
200	            eprintln!("error: {message}");
201	            eprintln!("{USAGE}");
202	            std::process::exit(2);
203	        }
204	    };
205	    if let Err(error) = run(&settings) {
206	        eprintln!("error: {error}");
207	        std::process::exit(1);
208	    }
209	}
