    35	        let mut nearest: Option<HitRecord> = None;
    36	        for object in &self.objects {
    37	            let limit = nearest.map_or(t_max, |hit| hit.t);
    38	            if let Some(hit) = object.hit(ray, t_min, limit) {
    39	                nearest = Some(hit);
    40	            }
    41	        }
    42	        nearest
    43	    }
    44	}
