    10	pub struct Sphere {
    11	    pub center: Vec3,
    12	    pub radius: f64,
    13	}
    14	
    15	impl Sphere {
    16	    pub fn new(center: Vec3, radius: f64) -> Self {
    17	        Sphere { center, radius }
    18	    }
    19	}
    20	
    21	impl Hittable for Sphere {
    22	    fn hit(&self, ray: &Ray, t_min: f64, t_max: f64) -> Option<HitRecord> {
    23	        let oc = ray.origin - self.center;
    24	        let a = ray.direction.dot(ray.direction);
    25	        let half_b = oc.dot(ray.direction);
    26	        let c = oc.dot(oc) - self.radius * self.radius;
    27	        let discriminant = half_b * half_b - a * c;
    28	        if discriminant < 0.0 {
    29	            return None;
    30	        }
    31	        let root = discriminant.sqrt();
    32	        let mut t = (-half_b - root) / a;
    33	        if t <= t_min || t >= t_max {
    34	            t = (-half_b + root) / a;
    35	            if t <= t_min || t >= t_max {
    36	                return None;
    37	            }
    38	        }
    39	        let point = ray.at(t);
    40	        let outward_normal = (point - self.center) / self.radius;
    41	        let theta = (-outward_normal.y).acos();
    42	        let phi = (-outward_normal.z).atan2(outward_normal.x) + PI;
    43	        let u = phi / (2.0 * PI);
    44	        let v = theta / PI;
    45	        Some(HitRecord::new(ray, t, point, outward_normal, u, v))
    46	    }
    47	
    48	    fn bounding_box(&self) -> Option<Aabb> {
    49	        let extent = Vec3::new(self.radius, self.radius, self.radius);
    50	        Some(Aabb::new(self.center - extent, self.center + extent))
    51	    }
    52	}
