     7	/// An infinite plane: a point on it and its unit normal.
     8	pub struct Plane {
     9	    pub point: Vec3,
    10	    pub normal: Vec3,
    11	}
    12	
    13	impl Plane {
    14	    /// Build a plane through `point` with unit normal `normal`.
    15	    pub fn new(point: Vec3, normal: Vec3) -> Self {
    16	        Plane { point, normal }
    17	    }
    18	}
    19	
    20	impl Hittable for Plane {
    21	    fn hit(&self, ray: &Ray, t_min: f64, t_max: f64) -> Option<HitRecord> {
    22	        let denominator = ray.direction.dot(self.normal);
    23	        if denominator == 0.0 {
    24	            return None;
    25	        }
    26	        let t = (self.point - ray.origin).dot(self.normal) / denominator;
    27	        if t <= t_min || t >= t_max {
    28	            return None;
    29	        }
    30	        let point = ray.at(t);
    31	        let tangent = if self.normal.x.abs() > self.normal.y.abs() {
    32	            Vec3::new(-self.normal.z, 0.0, self.normal.x).unit()
    33	        } else {
    34	            Vec3::new(0.0, -self.normal.z, self.normal.y).unit()
    35	        };
    36	        let bitangent = self.normal.cross(tangent);
    37	        let u = point.dot(tangent).rem_euclid(1.0);
    38	        let v = point.dot(bitangent).rem_euclid(1.0);
    39	        Some(HitRecord::new(ray, t, point, self.normal, u, v))
    40	    }
    41	}
