     8	/// A triangle: its three vertices, counter-clockwise seen from its front face.
     9	pub struct Triangle {
    10	    pub a: Vec3,
    11	    pub b: Vec3,
    12	    pub c: Vec3,
    13	}
    14	
    15	impl Triangle {
    16	    /// Build a triangle from its three vertices, counter-clockwise seen from its front face.
    17	    pub fn new(a: Vec3, b: Vec3, c: Vec3) -> Self {
    18	        Triangle { a, b, c }
    19	    }
    20	}
    21	
    22	impl Hittable for Triangle {
    23	    fn hit(&self, ray: &Ray, t_min: f64, t_max: f64) -> Option<HitRecord> {
    24	        let edge1 = self.b - self.a;
    25	        let edge2 = self.c - self.a;
    26	        let h = ray.direction.cross(edge2);
    27	        let determinant = edge1.dot(h);
    28	        if determinant.abs() < 1e-9 {
    29	            return None;
    30	        }
    31	        let inverse = 1.0 / determinant;
    32	        let s = ray.origin - self.a;
    33	        let u = inverse * s.dot(h);
    34	        if !(0.0..=1.0).contains(&u) {
    35	            return None;
    36	        }
    37	        let q = s.cross(edge1);
    38	        let v = inverse * ray.direction.dot(q);
    39	        if v < 0.0 || u + v > 1.0 {
    40	            return None;
    41	        }
    42	        let t = inverse * edge2.dot(q);
    43	        if t <= t_min || t >= t_max {
    44	            return None;
    45	        }
    46	        let point = ray.at(t);
    47	        let outward_normal = edge1.cross(edge2).unit();
    48	        Some(HitRecord::new(ray, t, point, outward_normal, u, v))
    49	    }
    50	
    51	    fn bounding_box(&self) -> Option<Aabb> {
    52	        let min = Vec3::new(
    53	            self.a.x.min(self.b.x).min(self.c.x),
    54	            self.a.y.min(self.b.y).min(self.c.y),
    55	            self.a.z.min(self.b.z).min(self.c.z),
    56	        );
    57	        let max = Vec3::new(
    58	            self.a.x.max(self.b.x).max(self.c.x),
    59	            self.a.y.max(self.b.y).max(self.c.y),
    60	            self.a.z.max(self.b.z).max(self.c.z),
    61	        );
    62	        Some(Aabb::new(min, max))
    63	    }
    64	}
